#include <stdio.h>
#include <stdlib.h>

static long long *power;

static int compare_ids(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    if (power[x] < power[y]) return -1;
    if (power[x] > power[y]) return 1;
    return x - y;
}

static int find_root(int *dsu, int x) {
    int root = x;
    while (dsu[root] != root) root = dsu[root];
    while (dsu[x] != x) {
        int next = dsu[x];
        dsu[x] = root;
        x = next;
    }
    return root;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int v = n * m;
    int max_nodes = 2 * v;
    power = malloc((size_t)v * sizeof(long long));
    int *order = malloc((size_t)v * sizeof(int));
    int *dsu = malloc((size_t)v * sizeof(int));
    int *dsu_size = malloc((size_t)v * sizeof(int));
    int *tree_root = malloc((size_t)v * sizeof(int));
    char *active = calloc((size_t)v, sizeof(char));

    long long *mass = malloc((size_t)max_nodes * sizeof(long long));
    long long *key = malloc((size_t)max_nodes * sizeof(long long));
    int *left = malloc((size_t)max_nodes * sizeof(int));
    int *right = malloc((size_t)max_nodes * sizeof(int));
    int *parent = malloc((size_t)max_nodes * sizeof(int));
    int *endpoint = malloc((size_t)max_nodes * sizeof(int));
    int *stack = malloc((size_t)max_nodes * sizeof(int));

    for (int i = 0; i < v; ++i) {
        scanf("%lld", &power[i]);
        order[i] = i;
        dsu[i] = i;
        dsu_size[i] = 1;
        tree_root[i] = i;
        mass[i] = power[i];
        key[i] = power[i];
        left[i] = right[i] = parent[i] = -1;
    }

    qsort(order, (size_t)v, sizeof(int), compare_ids);

    int nodes = v;
    for (int oi = 0; oi < v; ++oi) {
        int x = order[oi];
        active[x] = 1;

        int r = x / m;
        int c = x % m;
        int neighbors[4];
        int count = 0;

        if (r > 0) neighbors[count++] = x - m;
        if (r + 1 < n) neighbors[count++] = x + m;
        if (c > 0) neighbors[count++] = x - 1;
        if (c + 1 < m) neighbors[count++] = x + 1;

        for (int k = 0; k < count; ++k) {
            int y = neighbors[k];
            if (!active[y]) continue;

            int a = find_root(dsu, x);
            int b = find_root(dsu, y);
            if (a == b) continue;

            int node = nodes++;
            left[node] = tree_root[a];
            right[node] = tree_root[b];
            parent[left[node]] = node;
            parent[right[node]] = node;
            mass[node] = mass[left[node]] + mass[right[node]];
            key[node] = power[x];

            if (dsu_size[a] < dsu_size[b]) {
                int tmp = a;
                a = b;
                b = tmp;
            }
            dsu[b] = a;
            dsu_size[a] += dsu_size[b];
            tree_root[a] = node;
        }
    }

    int root = tree_root[find_root(dsu, 0)];
    int top = 0;
    stack[top++] = root;
    endpoint[root] = root;

    while (top > 0) {
        int node = stack[--top];
        int children[2] = {left[node], right[node]};

        for (int k = 0; k < 2; ++k) {
            int child = children[k];
            if (child == -1) continue;

            endpoint[child] = (key[node] <= mass[child])
                                  ? endpoint[node]
                                  : child;
            stack[top++] = child;
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int id = i * m + j;
            if (j) putchar(' ');
            printf("%lld", mass[endpoint[id]]);
        }
        putchar('\n');
    }

    free(power);
    free(order);
    free(dsu);
    free(dsu_size);
    free(tree_root);
    free(active);
    free(mass);
    free(key);
    free(left);
    free(right);
    free(parent);
    free(endpoint);
    free(stack);

    return 0;
}
